#include <iostream>
using namespace std;

static int resource_count = 0;

class FileHandle {
    int* resource;
public:
    FileHandle() { resource = new int(42); resource_count++; cout << "Acquired. Count: " << resource_count << endl; }
    ~FileHandle() { delete resource; resource_count--; cout << "Released. Count: " << resource_count << endl; }
    FileHandle(const FileHandle& other) {
        resource = new int(*other.resource);
        resource_count++;
        cout << "Copied. Count: " << resource_count << endl;
    }
};

int main() {
    FileHandle f1;
    {
        FileHandle f2 = f1;
        FileHandle f3;
    }
    cout << "End of scope\n";
    return 0;
}
